let cropState=null;
function openCropper(id,file){
  if(!file||!file.type.startsWith('image/'))return toast('فایل انتخاب‌شده تصویر نیست.');
  if(file.size>10*1024*1024)return toast('حجم تصویر باید حداکثر ۱۰ مگابایت باشد.');
  const reader=new FileReader();
  reader.onload=()=>{
    const img=new Image();
    img.onload=()=>{
      const modal=document.createElement('div'); modal.id='cropModal'; modal.className='crop-modal';
      modal.innerHTML=`<div class="crop-card" role="dialog" aria-modal="true" aria-label="برش تصویر محصول"><div class="crop-head"><div><span class="muted">IMAGE EDITOR</span><h2>پیش‌نمایش و برش تصویر</h2><p class="muted">کادر را جابه‌جا کن و زوم را تنظیم کن؛ دقیقاً همین قسمت آپلود می‌شود.</p></div><button class="crop-close" id="cropCancel">×</button></div><div class="crop-layout"><div class="crop-stage" id="cropStage"><canvas id="cropCanvas" width=800 height=600></canvas><div class="crop-frame"></div></div><div class="crop-controls"><label>بزرگ‌نمایی <input id="cropZoom" type="range" min=1 max=3 step=.01 value=1></label><div class="crop-preview-wrap"><span>پیش‌نمایش نهایی</span><canvas id="cropPreview" width=180 height=180></canvas></div><div class="crop-hint">نسبت تصویر: ۴:۳ · پیش‌نمایش دقیقاً مطابق تصویر سایت نمایش داده می‌شود</div><div class="crop-actions"><button class="secondary" id="cropCancel2">انصراف</button><button class="primary" id="cropConfirm">تأیید و آپلود</button></div></div></div></div>`;
      document.body.appendChild(modal);
      cropState={id,file,img,zoom:1,x:0,y:0,dragging:false,startX:0,startY:0,baseScale:1};
      setupCropper();
    }; img.src=reader.result;
  }; reader.readAsDataURL(file);
}
function setupCropper(){
  const canvas=$('#cropCanvas'), preview=$('#cropPreview'), stage=$('#cropStage'), zoom=$('#cropZoom');
  const ctx=canvas.getContext('2d'), pctx=preview.getContext('2d');
  const st=cropState, W=800, H=600, OUT_W=1200, OUT_H=900;
  canvas.width=W; canvas.height=H; preview.width=360; preview.height=270;
  const iw=st.img.naturalWidth, ih=st.img.naturalHeight;
  st.baseScale=Math.max(W/iw,H/ih);
  const maxOffset=()=>{const scale=st.baseScale*st.zoom;return {x:Math.max(0,(iw*scale-W)/2),y:Math.max(0,(ih*scale-H)/2)}};
  function clamp(){const m=maxOffset();st.x=Math.max(-m.x,Math.min(m.x,st.x));st.y=Math.max(-m.y,Math.min(m.y,st.y));}
  function draw(){
    clamp();
    ctx.clearRect(0,0,W,H); ctx.fillStyle='#111'; ctx.fillRect(0,0,W,H);
    const scale=st.baseScale*st.zoom;
    const x=(W-iw*scale)/2+st.x, y=(H-ih*scale)/2+st.y;
    ctx.drawImage(st.img,x,y,iw*scale,ih*scale);
    pctx.clearRect(0,0,360,270); pctx.drawImage(canvas,0,0,360,270);
  }
  zoom.oninput=()=>{st.zoom=Number(zoom.value);draw()};
  const point=e=>{const r=canvas.getBoundingClientRect();const px=e.touches?e.touches[0].clientX:e.clientX;const py=e.touches?e.touches[0].clientY:e.clientY;return {x:(px-r.left)*(W/r.width),y:(py-r.top)*(H/r.height)}};
  const down=e=>{e.preventDefault();st.dragging=true;const q=point(e);st.startX=q.x-st.x;st.startY=q.y-st.y;};
  const move=e=>{if(!st.dragging)return;e.preventDefault();const q=point(e);st.x=q.x-st.startX;st.y=q.y-st.startY;draw()};
  const up=()=>{st.dragging=false};
  canvas.addEventListener('mousedown',down);window.addEventListener('mousemove',move);window.addEventListener('mouseup',up);
  canvas.addEventListener('touchstart',down,{passive:false});window.addEventListener('touchmove',move,{passive:false});window.addEventListener('touchend',up);
  function close(){window.removeEventListener('mousemove',move);window.removeEventListener('mouseup',up);window.removeEventListener('touchmove',move);modalRemove()}
  function modalRemove(){const m=$('#cropModal');if(m)m.remove();cropState=null}
  $('#cropCancel').onclick=close; $('#cropCancel2').onclick=close;
  $('#cropConfirm').onclick=async()=>{
    const out=document.createElement('canvas'); out.width=OUT_W; out.height=OUT_H;
    const octx=out.getContext('2d');
    const scale=st.baseScale*st.zoom;
    const x=(W-iw*scale)/2+st.x, y=(H-ih*scale)/2+st.y;
    octx.fillStyle='#f1eee5'; octx.fillRect(0,0,OUT_W,OUT_H);
    const sx=OUT_W/W, sy=OUT_H/H;
    octx.drawImage(st.img,x*sx,y*sy,iw*scale*sx,ih*scale*sy);
    $('#cropConfirm').disabled=true; $('#cropConfirm').textContent='در حال آپلود…';
    out.toBlob(async blob=>{try{
      if(!blob)throw Error('ساخت تصویر برش‌خورده ناموفق بود.');
      const fd=new FormData(); fd.append('image',blob,'aria-product.jpg');
      await api('/api/admin/products/'+st.id+'/image',{method:'POST',body:fd});
      toast('تصویر دقیقاً مطابق پیش‌نمایش آپلود شد.'); close(); await loadProducts();
    }catch(e){alert(e.message);$('#cropConfirm').disabled=false;$('#cropConfirm').textContent='تأیید و آپلود'}},'image/jpeg',.9);
  };
  draw();
}
