async function closeDay(){const reasons=[['end_of_hours','پایان ساعت کاری'],['official_holiday','تعطیل رسمی'],['no_courier','نبود پیک'],['capacity','تکمیل ظرفیت سفارش‌ها'],['technical','مشکل فنی یا تعمیرات'],['temporary','تعطیلی موقت'],['other','سایر']];const choice=prompt('دلیل پایان روز/سفارش‌گیری را انتخاب کن:\n\n1) پایان ساعت کاری\n2) تعطیل رسمی\n3) نبود پیک\n4) تکمیل ظرفیت سفارش‌ها\n5) مشکل فنی یا تعمیرات\n6) تعطیلی موقت\n7) سایر\n\nشماره گزینه را وارد کن:','1');if(choice===null)return;const idx=Number(choice)-1;if(!Number.isInteger(idx)||idx<0||idx>=reasons.length)return toast('گزینه دلیل نامعتبر است.');let custom='';if(reasons[idx][0]==='other'){custom=prompt('دلیل را بنویس:','');if(custom===null)return;}else{const extra=prompt('اگر توضیح کوتاهی لازم است بنویس (اختیاری):','');if(extra===null)return;custom=extra.trim();}if(!confirm(`سفارش‌گیری بسته شود؟\n\nدلیل: ${reasons[idx][1]}${custom?` — ${custom}`:''}`))return;try{const {ordering}=await api('/api/admin/day/close',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reasonCode:reasons[idx][0],customReason:custom})});renderStoreStatus(ordering);toast('سفارش‌گیری بسته شد و دلیل در سایت نمایش داده می‌شود.');if($('#settings')&&!$('#settings').hidden)loadSettings()}catch(e){alert(e.message)}}
async function reopenDay(){if(!confirm('سفارش‌گیری دوباره فعال شود؟'))return;try{const {ordering}=await api('/api/admin/day/reopen',{method:'POST'});renderStoreStatus(ordering);toast('سفارش‌گیری دوباره فعال شد.');if($('#settings')&&!$('#settings').hidden)loadSettings()}catch(e){alert(e.message)}}
