async function saveSettings(e){e.preventDefault();const f=new FormData(e.target);const phones=[...new Set(f.getAll('phones').map(x=>String(x||'').trim()).filter(Boolean))].slice(0,5);const payload={businessName:String(f.get('businessName')||'').trim(),phones,phone:phones[0]||'',address:String(f.get('address')||'').trim(),workingHours:String(f.get('workingHours')||'').trim(),instagramUrl:String(f.get('instagramUrl')||'').trim(),menuNotice:String(f.get('menuNotice')||'').trim(),aboutText:String(f.get('aboutText')||'').trim(),preparationMinutes:Number(f.get('preparationMinutes')),minimumOrder:Number(f.get('minimumOrder')),freeDeliveryOver:Number(f.get('freeDeliveryOver')),pickupEnabled:f.get('pickupEnabled')==='on',deliveryEnabled:f.get('deliveryEnabled')==='on',scheduleEnabled:f.get('scheduleEnabled')==='on',scheduleStart:String(f.get('scheduleStart')||'08:00'),scheduleEnd:String(f.get('scheduleEnd')||'24:00'),deliveryLocationAddress:String(f.get('deliveryLocationAddress')||'').trim(),deliveryCenterLat:Number(f.get('deliveryCenterLat')),deliveryCenterLng:Number(f.get('deliveryCenterLng')),deliveryZones:readDeliveryZonesFromForm()};const btn=e.submitter||e.target.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{await api('/api/admin/settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});toast('تنظیمات فروشگاه ذخیره شد.');await Promise.all([loadSettings(),loadStoreStatus()]);}catch(err){alert(err.message)}finally{if(btn)btn.disabled=false}}

async function loadStats(){
  const [{metrics,statusCounts,daily,topProducts,topCategories},orderData]=await Promise.all([api('/api/admin/analytics?range=30'),api('/api/admin/orders?date='+encodeURIComponent(dateKey(new Date()))) ]);
  allOrders=orderData.orders;
  const days=daily.slice(-10).reverse();
  const rows=days.map((d,i)=>`<tr class="history-row" onclick="showDay('${d.key}')"><td>${i===0?'امروز':i===1?'دیروز':new Intl.DateTimeFormat('fa-IR',{timeZone:TZ,weekday:'long',day:'numeric',month:'long'}).format(dateFromKey(d.key))}</td><td>${fa(d.completed)}</td><td>${fa(d.revenue)} تومان</td><td>مشاهده سفارش‌ها ←</td></tr>`).join('');
  const dailyBars=daily.map(d=>`<div class="bar-col" title="${d.key}: ${fa(d.revenue)} تومان"><span style="height:${Math.max(4,Math.round((d.revenue/(Math.max(...daily.map(x=>x.revenue),1)))*150))}px"></span><small>${d.key.slice(5)}</small></div>`).join('');
  const productRows=topProducts.map((p,i)=>`<tr><td>${fa(i+1)}</td><td>${escapeHtml(p.name)}</td><td>${fa(p.quantity)}</td><td>${fa(p.revenue)} تومان</td></tr>`).join('')||'<tr><td colspan="4">هنوز فروش تکمیل‌شده‌ای ثبت نشده.</td></tr>';
  const categoryRows=topCategories.map((c,i)=>`<tr><td>${fa(i+1)}</td><td>${escapeHtml(c.name)}</td><td>${fa(c.quantity)}</td><td>${fa(c.revenue)} تومان</td></tr>`).join('')||'<tr><td colspan="4">هنوز فروش تکمیل‌شده‌ای ثبت نشده.</td></tr>';
  $('#stats').innerHTML=`<div class="dashboard-head"><div><span class="muted">ARIA BUSINESS ANALYTICS</span><h1>داشبورد فروش</h1><p class="muted">گزارش ۳۰ روز اخیر · فروش فقط از سفارش‌های تکمیل‌شده محاسبه می‌شود.</p></div><div id="storeStatus"></div></div>
  <div class="cards analytics-cards"><div class="stat"><span>فروش ۳۰ روز</span><b>${fa(metrics.revenue)} تومان</b></div><div class="stat"><span>سفارش تکمیل‌شده</span><b>${fa(metrics.completed)}</b></div><div class="stat"><span>میانگین سفارش</span><b>${fa(metrics.averageOrder)} تومان</b></div><div class="stat"><span>نرخ تکمیل</span><b>${fa(metrics.completionRate)}٪</b></div><div class="stat"><span>سفارش لغوشده</span><b>${fa(metrics.cancelled)}</b></div><div class="stat"><span>کل سفارش‌ها</span><b>${fa(metrics.orders)}</b></div></div>
  <div class="analytics-grid"><div class="sales-history"><div class="history-head"><div><span class="muted">DAILY SALES</span><h2>روند فروش ۳۰ روز اخیر</h2></div></div><div class="bar-chart">${dailyBars}</div></div><div class="sales-history"><div class="history-head"><div><span class="muted">ORDER MIX</span><h2>نوع دریافت</h2></div></div><div class="mix-cards"><div><b>${fa(metrics.fulfillment.pickup)}</b><span>تحویل حضوری</span></div><div><b>${fa(metrics.fulfillment.delivery)}</b><span>ارسال</span></div></div><div class="status-summary">${statusOrder.map(st=>`<div><span>${labels[st]}</span><b>${fa(statusCounts[st]||0)}</b></div>`).join('')}</div></div></div>
  <div class="analytics-grid"><div class="sales-history"><div class="history-head"><div><span class="muted">TOP PRODUCTS</span><h2>پرفروش‌ترین محصولات</h2></div></div><div class="table-wrap"><table><thead><tr><th>#</th><th>محصول</th><th>تعداد</th><th>فروش</th></tr></thead><tbody>${productRows}</tbody></table></div></div><div class="sales-history"><div class="history-head"><div><span class="muted">TOP CATEGORIES</span><h2>پرفروش‌ترین دسته‌ها</h2></div></div><div class="table-wrap"><table><thead><tr><th>#</th><th>دسته</th><th>تعداد</th><th>فروش</th></tr></thead><tbody>${categoryRows}</tbody></table></div></div></div>
  <div class="sales-history"><div class="history-head"><div><span class="muted">SALES HISTORY</span><h2>فروش و سفارش‌های ۱۰ روز اخیر</h2></div><span class="muted">برای دیدن سفارش‌های هر روز کلیک کن.</span></div><div class="table-wrap"><table><thead><tr><th>روز</th><th>سفارش تکمیل‌شده</th><th>فروش واقعی</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div>`;
  renderStoreStatus((await api('/api/admin/day/status')).ordering);
}
async function showDay(key){selectedDate=key;orderStatusFilter='all';orderSearch='';await loadOrders(key);$$('aside button').forEach(x=>x.classList.toggle('active',x.dataset.tab==='orders'));$$('.tab').forEach(x=>x.hidden=x.id!=='orders');}
let liveSource=null;let liveRetryTimer=null;
function connectLive(){if(liveSource){try{liveSource.close()}catch{}};liveSource=new EventSource('/api/admin/events');liveSource.addEventListener('ready',()=>{$('#live')?.classList.remove('offline')});liveSource.addEventListener('order.created',e=>{let order=null;try{order=JSON.parse(e.data)}catch{};if(order)addOrderNotification(order);loadOrders(selectedDate);loadStats();});liveSource.addEventListener('order.overdue',e=>{let payload=null;try{payload=JSON.parse(e.data)}catch{};if(payload?.order)addAdminNotification(payload);loadOrders(selectedDate);});liveSource.addEventListener('order.updated',()=>{loadOrders(selectedDate);loadStats();});liveSource.addEventListener('product.updated',()=>loadProducts());liveSource.addEventListener('product.deleted',()=>loadProducts());liveSource.addEventListener('categories.updated',()=>loadProducts());liveSource.addEventListener('store.updated',e=>{try{renderStoreStatus(JSON.parse(e.data))}catch{}});liveSource.addEventListener('settings.updated',()=>{loadStoreStatus();if($('#settings')&&!$('#settings').hidden)loadSettings()});liveSource.onerror=()=>{ $('#live')?.classList.add('offline'); try{liveSource.close()}catch{};clearTimeout(liveRetryTimer);liveRetryTimer=setTimeout(connectLive,3000)};}
$('#logout').onclick=async()=>{const btn=$('#logout');if(btn?.disabled)return;if(btn)btn.disabled=true;try{await api('/api/admin/logout',{method:'POST'});}catch(e){console.warn('Logout request failed:',e)}finally{showLogin();if($('#loginError'))$('#loginError').textContent='';if($('#loginForm'))$('#loginForm').reset();if(btn)btn.disabled=false;try{liveSource?.close()}catch{};window.__ariaNotificationsBound=false;clearInterval(window.__ariaNotificationPoll);}};boot();

let couponEditId=null;
async function loadCoupons(){if(!window.__adminProducts||!window.__adminCategories){const data=await api('/api/admin/products');window.__adminProducts=data.products;window.__adminCategories=data.categories;}const {coupons}=await api('/api/admin/coupons');const el=$('#coupons');if(!el)return;const activeCount=coupons.filter(c=>c.active!==false).length;const usedTotal=coupons.reduce((n,c)=>n+Number(c.usedCount||0),0);el.innerHTML=`<div class="coupon-page"><div class="panel-head coupon-page-head"><div><span class="muted">DISCOUNTS</span><h2>کدهای تخفیف</h2><p class="muted">کدهای تخفیف را بساز، شرایط استفاده را تعیین کن و عملکردشان را کنترل کن.</p></div><button class="primary" id="newCoupon">+ ساخت کد تخفیف</button></div><div class="coupon-stats"><div><span>کدهای فعال</span><b>${fa(activeCount)}</b></div><div><span>کل کدها</span><b>${fa(coupons.length)}</b></div><div><span>دفعات استفاده</span><b>${fa(usedTotal)}</b></div></div><div class="coupon-admin-list">${coupons.length?coupons.map(c=>{const limit=Number(c.usageLimit||0);const status=c.active===false?'غیرفعال':limit>0&&Number(c.usedCount||0)>=limit?'تکمیل ظرفیت':(c.expiresAt&&new Date(c.expiresAt)<new Date()?'منقضی شده':'فعال');const statusClass=status==='فعال'?'on':'off';return `<article class="coupon-card"><div class="coupon-card-main"><div class="coupon-code-line"><span class="coupon-code">${escapeHtml(c.code)}</span><span class="toggle ${statusClass}">${status}</span></div><div class="coupon-meta"><span>${c.type==='percent'?`تخفیف ${fa(c.amount)}٪`:`تخفیف ${fa(c.amount)} تومان`}</span><span>حداقل سفارش: ${fa(c.minOrder||0)} تومان</span>${Number(c.maxDiscount||0)?`<span>سقف تخفیف: ${fa(c.maxDiscount)} تومان</span>`:''}<span>استفاده: ${fa(c.usedCount||0)}${limit?` / ${fa(limit)}`:' / نامحدود'}</span>${c.firstOrder?'<span>فقط اولین سفارش</span>':''}</div></div><div class="coupon-card-actions"><button class="toggle" onclick="editCoupon('${c.id}')">ویرایش</button><button class="toggle delete-product" onclick="deleteCoupon('${c.id}')">حذف</button></div></article>`}).join(''):'<div class="empty-products coupon-empty"><b>هنوز کد تخفیفی نساختی.</b><span>برای شروع روی «ساخت کد تخفیف» بزن.</span></div>'}</div></div>`;$('#newCoupon').onclick=()=>openCouponForm();}
function openCouponForm(c={}){const isEdit=Boolean(c.id);const categories=(window.__adminCategories||[]).filter(x=>x.active!==false).sort((a,b)=>(a.sort||0)-(b.sort||0));const products=(window.__adminProducts||[]).filter(x=>x.available!==false).sort((a,b)=>String(a.name).localeCompare(String(b.name),'fa'));const selectedProducts=new Set(c.productIds||[]);const selectedCategories=new Set(c.categoryIds||[]);const el=document.createElement('div');el.className='modal-backdrop';el.innerHTML=`<div class="admin-modal coupon-modal" role="dialog" aria-modal="true"><button class="close" data-x type="button">×</button><div class="coupon-modal-head"><span class="muted">DISCOUNT CODE</span><h2>${isEdit?'ویرایش کد تخفیف':'ساخت کد تخفیف'}</h2><p class="muted">شرایط را دقیق تنظیم کن؛ مبلغ نهایی در سمت سرور دوباره محاسبه می‌شود.</p></div><div class="coupon-form-grid"><label class="full-field">کد تخفیف<input id="cpCode" maxlength="40" value="${escapeHtml(c.code||'')}" placeholder="مثلاً ARIA20" autocomplete="off"><small>فقط حروف انگلیسی، عدد، خط تیره و زیرخط</small></label><label>نوع تخفیف<select id="cpType"><option value="percent" ${c.type!=='fixed'?'selected':''}>درصدی</option><option value="fixed" ${c.type==='fixed'?'selected':''}>مبلغ ثابت</option></select></label><label>مقدار تخفیف<div class="unit-input"><input id="cpAmount" type="number" min="1" max="1000000000" step="1" value="${c.amount||''}" placeholder="مثلاً ۲۰"><span id="cpAmountUnit">%</span></div></label><label>حداقل مبلغ سفارش<div class="unit-input"><input id="cpMin" type="number" min="0" step="1" value="${c.minOrder||0}"><span>تومان</span></div></label><label>حداکثر مبلغ تخفیف<div class="unit-input"><input id="cpMax" type="number" min="0" step="1" value="${c.maxDiscount||0}"><span>تومان</span></div><small>۰ یعنی بدون سقف</small></label><label>حداکثر استفاده<div class="unit-input"><input id="cpLimit" type="number" min="0" step="1" value="${c.usageLimit||0}"><span>بار</span></div><small>۰ یعنی نامحدود</small></label><label>شروع اعتبار<input id="cpStarts" type="datetime-local" value="${toDateInput(c.startsAt)}"></label><label>پایان اعتبار<input id="cpExpires" type="datetime-local" value="${toDateInput(c.expiresAt)}"></label></div><div class="coupon-target-box"><div class="coupon-section-title"><b>محدوده اعمال</b><span class="muted">اختیاری؛ خالی یعنی روی همه محصولات</span></div><div class="coupon-target-grid"><label>دسته‌بندی‌ها<select id="cpCategories" multiple>${categories.map(x=>`<option value="${x.id}" ${selectedCategories.has(x.id)?'selected':''}>${escapeHtml(x.name)}</option>`).join('')}</select></label><label>محصولات<select id="cpProducts" multiple>${products.map(x=>`<option value="${x.id}" ${selectedProducts.has(x.id)?'selected':''}>${escapeHtml(x.name)}</option>`).join('')}</select></label></div><small class="muted">برای انتخاب چند مورد، روی ویندوز با Ctrl و روی مک با Command انتخاب کن.</small></div><div class="coupon-switches"><label><input id="cpFirst" type="checkbox" ${c.firstOrder?'checked':''}> فقط اولین سفارش مشتری</label><label><input id="cpActive" type="checkbox" ${c.active!==false?'checked':''}> کد فعال باشد</label></div><div class="coupon-preview" id="couponPreview"></div><div class="coupon-modal-actions"><button class="secondary" id="cpCancel" type="button">انصراف</button><button class="primary" id="cpSave" type="button">${isEdit?'ذخیره تغییرات':'ساخت کد تخفیف'}</button></div></div>`;document.body.appendChild(el);const typeEl=el.querySelector('#cpType'),amountUnit=el.querySelector('#cpAmountUnit'),preview=el.querySelector('#couponPreview');const updateType=()=>{const fixed=typeEl.value==='fixed';amountUnit.textContent=fixed?'تومان':'٪';el.querySelector('#cpAmount').max=fixed?'1000000000':'100';renderCouponPreview()};const renderCouponPreview=()=>{const code=String(el.querySelector('#cpCode').value||'ARIA20').toUpperCase().trim()||'ARIA20';const amount=Number(el.querySelector('#cpAmount').value)||0;const min=Number(el.querySelector('#cpMin').value)||0;const max=Number(el.querySelector('#cpMax').value)||0;preview.innerHTML=`<div><span>پیش‌نمایش</span><b>${escapeHtml(code)}</b></div><p>${typeEl.value==='fixed'?`۵۰٬۰۰۰ تومان`:'۲۰٪'} تخفیف${min?` برای سفارش‌های بالای ${fa(min)} تومان`:''}${max?` · سقف ${fa(max)} تومان`:''}</p>`};typeEl.onchange=updateType;['#cpCode','#cpAmount','#cpMin','#cpMax'].forEach(sel=>el.querySelector(sel).addEventListener('input',renderCouponPreview));el.querySelector('[data-x]').onclick=()=>el.remove();el.querySelector('#cpCancel').onclick=()=>el.remove();el.addEventListener('click',e=>{if(e.target===el)el.remove()});el.querySelector('#cpSave').onclick=async()=>{const amount=Number(el.querySelector('#cpAmount').value);if(typeEl.value==='percent'&&(amount<1||amount>100))return alert('درصد تخفیف باید بین ۱ تا ۱۰۰ باشد.');if(typeEl.value==='fixed'&&amount<1)return alert('مبلغ تخفیف باید بیشتر از صفر باشد.');const starts=fromDateInput(el.querySelector('#cpStarts').value);const expires=fromDateInput(el.querySelector('#cpExpires').value);if(starts&&expires&&new Date(starts)>new Date(expires))return alert('تاریخ شروع نمی‌تواند بعد از پایان اعتبار باشد.');const payload={code:el.querySelector('#cpCode').value,type:typeEl.value,amount,minOrder:Number(el.querySelector('#cpMin').value)||0,maxDiscount:Number(el.querySelector('#cpMax').value)||0,usageLimit:Number(el.querySelector('#cpLimit').value)||0,startsAt:starts||null,expiresAt:expires||null,firstOrder:el.querySelector('#cpFirst').checked,active:el.querySelector('#cpActive').checked,productIds:[...el.querySelector('#cpProducts').selectedOptions].map(o=>o.value),categoryIds:[...el.querySelector('#cpCategories').selectedOptions].map(o=>o.value)};const btn=el.querySelector('#cpSave');btn.disabled=true;try{await api(isEdit?'/api/admin/coupons/'+c.id:'/api/admin/coupons',{method:isEdit?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});el.remove();toast('کد تخفیف با موفقیت ذخیره شد.');loadCoupons()}catch(e){alert(e.message);btn.disabled=false}};updateType();renderCouponPreview();}
function toDateInput(v){if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return '';const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function fromDateInput(v){if(!v)return null;const d=new Date(v);return Number.isNaN(d.getTime())?null:d.toISOString()}
async function editCoupon(id){const {coupons}=await api('/api/admin/coupons');const c=coupons.find(x=>x.id===id);if(c){const {products,categories}=await api('/api/admin/products');window.__adminProducts=products;window.__adminCategories=categories;openCouponForm(c)}}
async function deleteCoupon(id){if(!confirm('این کد تخفیف حذف شود؟'))return;try{await api('/api/admin/coupons/'+id,{method:'DELETE'});toast('کد تخفیف حذف شد.');loadCoupons()}catch(e){alert(e.message)}}
